export const CATALOG: CatalogExercise[] = ROWS.map(([id, name, group, logKind, muscle, equipment, level]) => ({
  id, name, group, logKind: logKind as LogKind, muscle, equipment, level,
}));

export const CATALOG_BY_ID: Record<string, CatalogExercise> =
  Object.fromEntries(CATALOG.map((e) => [e.id, e]));

/** Distinct facet values for the search filters. */
export const CATALOG_MUSCLES: string[] = [...new Set(CATALOG.map((e) => e.muscle).filter(Boolean))].sort();
export const CATALOG_EQUIPMENT: string[] = [...new Set(CATALOG.map((e) => e.equipment).filter(Boolean))].sort();

/**
 * Lightweight search: every whitespace-separated query token must appear in
 * the name/muscle/equipment/group haystack. Optional facet filters narrow
 * first. Ranked: name-prefix matches, then name-substring, then the rest.
 */
export function searchCatalog(
  query: string,
  opts?: { muscle?: string | null; equipment?: string | null; kind?: LogKind | null; limit?: number },
): CatalogExercise[] {
  const q = query.trim().toLowerCase();
  const tokens = q.split(/\s+/).filter(Boolean);
  const { muscle, equipment, kind, limit = 60 } = opts ?? {};
  const scored: { e: CatalogExercise; score: number }[] = [];
  for (const e of CATALOG) {
    if (muscle && e.muscle !== muscle) continue;
    if (equipment && e.equipment !== equipment) continue;
    if (kind && e.logKind !== kind) continue;
    const name = e.name.toLowerCase();
    if (tokens.length) {
      const hay = (name + ' ' + e.muscle + ' ' + e.equipment + ' ' + e.group).toLowerCase();
      if (!tokens.every((t) => hay.includes(t))) continue;
    }
    let score = 1;
    if (q && name.startsWith(q)) score = 3;
    else if (q && name.includes(q)) score = 2;
    scored.push({ e, score });
  }
  scored.sort((a, b) => b.score - a.score || a.e.name.localeCompare(b.e.name));
  return scored.slice(0, limit).map((s) => s.e);
}
